// cloudflare-env.d.ts is generated by `wrangler types` from wrangler.jsonc
// bindings only, so plain secrets (never declared there — see wrangler.jsonc)
// don't appear in it. This merges them into the same global CloudflareEnv
// interface by declaration merging.
interface CloudflareEnv {
  STRIPE_SECRET_KEY: string;
  STRIPE_WEBHOOK_SECRET: string;
}
